style.css:
@-moz-document domain("roblox.com"), domain("www.roblox.com"), domain("create.roblox.com"), domain("avatar.roblox.com"), domain("web.roblox.com") {
body {
        background: url("https://i.pinimg.com/736x/05/c5/68/05c568a016d0ec0fe517d86a5aa4fc83.jpg") 
                    no-repeat center center fixed !important;
        background-size: cover !important;
    }

    /* Header color */
    .rbx-header {
        background-color: #E47B8D !important;
        box-shadow: none !important;
        border: none !important;
    }

    /* Sidebar color */
    .left-col {
        background-color: #E47B8D !important;
        box-shadow: none !important;
        border: none !important;
    }

    /* Optional: make content area slightly see-through */
    .content, .container, .section, .footer-container {
        background-color: rgba(255, 255, 255, 0.85) !important;
    }
}
